<?php
namespace App\Domain\Storage\Services;
use App\Models\{DocumentFile,FileIntegrityCheck,SecurityEvent};use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;
class IntegrityScanner{public function scan(DocumentFile $file,string $type='SCHEDULED'):bool{$disk=Storage::disk($file->storage_disk);$actual=null;$error=null;if(!$disk->exists($file->storage_key)){$result='MISSING';$error='Storage object missing.';}else{try{$actual=hash_file('sha256',$disk->path($file->storage_key));$result=hash_equals($file->sha256,$actual)?'PASS':'FAIL';}catch(\Throwable $e){$result='FAIL';$error=$e->getMessage();}}FileIntegrityCheck::create(['document_file_id'=>$file->id,'expected_sha256'=>$file->sha256,'calculated_sha256'=>$actual,'result'=>$result,'checked_by_type'=>$type,'error_message'=>$error,'checked_at'=>now()]);if($result!=='PASS')SecurityEvent::create(['event_ulid'=>(string)Str::ulid(),'user_id'=>null,'event_type'=>'CHECKSUM_MISMATCH','severity'=>'CRITICAL','result'=>$result,'username_snapshot'=>'SYSTEM','context'=>['document_file_id'=>$file->id,'storage_key_hash'=>hash('sha256',$file->storage_key)],'occurred_at'=>now()]);return $result==='PASS';}}
